41: inline QString layoutName(const QString& fallback, std::size_t count, bool custom) {
42:     if (count == 0) return fallback;
43:     if (custom) return UI::localizedText("meterbridge", "layout.custom", "Custom %1").arg(count);
44:     switch (count) {
45:     case 1: return UI::localizedText("meterbridge", "layout.mono", "Mono");

43:     if (custom) return UI::localizedText("meterbridge", "layout.custom", "Custom %1").arg(count);
44:     switch (count) {
45:     case 1: return UI::localizedText("meterbridge", "layout.mono", "Mono");
46:     case 2: return UI::localizedText("meterbridge", "layout.stereo", "Stereo");
47:     case 6: return QStringLiteral("5.1");

44:     switch (count) {
45:     case 1: return UI::localizedText("meterbridge", "layout.mono", "Mono");
46:     case 2: return UI::localizedText("meterbridge", "layout.stereo", "Stereo");
47:     case 6: return QStringLiteral("5.1");
48:     case 8: return QStringLiteral("7.1");

47:     case 6: return QStringLiteral("5.1");
48:     case 8: return QStringLiteral("7.1");
49:     default: return UI::localizedText("meterbridge", "layout.multichannel", "Multichannel %1").arg(count);
50:     }
51: }

